#!/usr/bin/env node
/**
 * Generate the DSH patch for the GEO Radar MCP bridge.
 *
 * Usage:
 *   GEO_RADAR_URL=http://127.0.0.1:3000 GEO_RADAR_TOKEN=gr_... \
 *     node scripts/install-dsh-plugin.mjs
 *
 * The generated file contains the token and is gitignored.
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { resolve, dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { homedir } from "node:os";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const envFile = resolve(root, ".env.local");
if (existsSync(envFile)) {
  for (const line of readFileSync(envFile, "utf8").split(/\r?\n/)) {
    const m = /^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/.exec(line.trim());
    if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
  }
}

const token = process.env.GEO_RADAR_TOKEN || process.argv[2];
const baseUrl = (process.env.GEO_RADAR_URL || "http://127.0.0.1:3000").replace(/\/+$/, "");
if (!token || !token.startsWith("gr_")) {
  console.error("缺少 GEO_RADAR_TOKEN（应形如 gr_...）。先运行：");
  console.error('  npm run token:create -- you@example.com "DSH MCP"');
  process.exit(1);
}
if (!/^https?:\/\//.test(baseUrl)) {
  console.error("GEO_RADAR_URL 必须是 http(s) URL");
  process.exit(1);
}

const mcpPath = resolve(root, "packages/geo-radar-mcp/index.mjs");
if (!existsSync(mcpPath)) {
  console.error(`找不到 MCP server: ${mcpPath}`);
  process.exit(1);
}
const q = (v) => JSON.stringify(v);
const patch = `# Generated by scripts/install-dsh-plugin.mjs — contains a token, do not commit.
- insert:
    - id: mcp-geo-radar
      name: '@deepseek-ai/dsh-mcp-client'
      config:
        serverName: geo-radar
        transport: stdio
        command: node
        args:
          - ${q(mcpPath)}
        env:
          GEO_RADAR_URL: ${q(baseUrl)}
          GEO_RADAR_TOKEN: ${q(token)}
          NODE_NO_WARNINGS: "1"
`;
const out = resolve(root, "packages/dsh-geo-radar/cordis.patch.yml");
writeFileSync(out, patch, { encoding: "utf8", mode: 0o600 });
const profile =
  process.env.DSH_PROFILE ||
  (existsSync(join(homedir(), ".dsh", "profiles", "desktop")) ? "desktop" : "web");
console.log("DSH patch written:", out);
console.log("");
console.log("Next (run inside the package directory to avoid spaces in the absolute path):");
console.log(`  cd "${resolve(root, "packages/dsh-geo-radar")}"`);
console.log(`  dsh plugin --profile ${profile} add .`);
console.log("  # restart DSH, then look for mcp__geo-radar__geo_* tools");
